mapper.update:
UPDATE medication_logs 
SET taken_time = #{takenTime}, dosage_taken = #{dosageTaken}, status = #{status}
WHERE id = #{id}

mapper.select:
SELECT ml.*, um.custom_name as medicine_name, um.dose_unit
FROM medication_logs ml
LEFT JOIN user_medicines um ON ml.user_medicine_id = um.id
WHERE ml.user_medicine_id = #{userMedicineId}
ORDER BY ml.scheduled_time DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM medication_logs 
WHERE user_medicine_id = #{userMedicineId}
AND status = 'pending'
AND scheduled_time > #{afterTime}
